let importedMeshes=[],meshLoads=new Set();
function loadProjectMeshes(){if(!native)return;for(const layer of layers.flatMap(l=>[l,...(l.effect.eventRules||[]).filter(r=>r.response).map(r=>({enabled:l.enabled,effect:r.response}))]))if(layer.enabled&&layer.effect.renderer==='mesh'&&!viewport?.meshLibrary.has(layer.effect.meshRef)&&!meshLoads.has(layer.effect.meshRef)){const reference=layer.effect.meshRef;meshLoads.add(reference);native.getBlenderMesh(reference).then(async result=>{if(result.ok)await prepareMesh(result.mesh);else toast('A mesh is missing. Import its original file again.');}).catch(error=>toast(error.message));}}

async function prepareMesh(mesh){await viewport?.loadParticleMesh(mesh);if(!importedMeshes.some(item=>item.id===mesh.id))importedMeshes.push({id:mesh.id,name:mesh.name});renderMeshControls();}
function renderMeshControls(){const renderer=$('#particle-renderer'),select=$('#particle-mesh');renderer.value=state.renderer||'sprite';$('#advanced-sprite').disabled=state.renderer==='mesh';select.replaceChildren();for(const mesh of importedMeshes){const option=document.createElement('option');option.value=mesh.id;option.textContent=mesh.name;select.append(option);}if(state.meshRef&&!importedMeshes.some(mesh=>mesh.id===state.meshRef)){const option=document.createElement('option');option.value=state.meshRef;option.textContent='Missing mesh — import the original file';select.append(option);}select.value=state.meshRef||'';$('#particle-mesh-label').hidden=state.renderer!=='mesh';}
async function importParticleMesh(){if(!native){toast('Blender mesh import is available in the desktop app.');return;}const result=await native.importBlenderMesh();if(result.ok&&!result.canceled){try{await prepareMesh(result.mesh);state.renderer='mesh';state.meshRef=result.mesh.id;state.meshAsset='';sync();persist();toast(result.mesh.name+' is now the particle shape');}catch(error){toast(error.message);return {ok:false,error:error.message};}}else if(!result.ok)toast(result.error);return result;}
$('#import-particle-mesh').onclick=importParticleMesh;
$('#particle-renderer').onchange=async event=>{if(event.target.value==='mesh'&&!state.meshRef){await importParticleMesh();renderMeshControls();return;}state.renderer=event.target.value;sync();persist();};
$('#particle-mesh').onchange=async event=>{const reference=event.target.value;try{if(native){const result=await native.getBlenderMesh(reference);if(!result.ok)throw Error(result.error);await prepareMesh(result.mesh);}state.meshRef=reference;state.meshAsset='';sync();persist();}catch(error){toast(error.message);renderMeshControls();}};
const meshSync=sync;sync=()=>{meshSync();renderMeshControls();loadProjectMeshes();};renderMeshControls();
if(native)native.listBlenderMeshes().then(async result=>{if(!result.ok)return;importedMeshes=result.meshes;renderMeshControls();loadProjectMeshes();for(const layer of layers)if(layer.effect.renderer==='mesh'){const result=await native.getBlenderMesh(layer.effect.meshRef);if(result.ok)await prepareMesh(result.mesh);else toast('A saved mesh is missing. Import its original file again.');}});
$('#blender-menu').onclick=async()=>{
 if(!native){toast('Blender support is available in the Ember desktop app.');return;}const status=await native.blenderStatus();
 dialog('<h2>Blender & file transfer</h2><p id="blender-installation"></p><button id="choose-blender">Choose Blender…</button><button id="launch-blender">Open Blender</button><hr><h3>Particle effects</h3><p>Export a baked animation that replays in Blender. Original Ember settings are kept inside the file so you can bring the effect back.</p><label>Duration (seconds)<input id="blender-duration" aria-label="Blender bake duration" type="number" min="1" max="20" step="1" value="5"></label><label>Frames per second<input id="blender-fps" aria-label="Blender bake frame rate" type="number" min="1" max="30" step="1" value="24"></label><button id="blender-export-effect" class="primary">Save effect as .blend…</button><button id="blender-recover-effect">Open Ember effect from .blend…</button><hr><h3>3D meshes</h3><p>Import .blend, .glb, or .fbx files as particle shapes. Static meshes can also move between Blender and your connected Unreal project.</p><button id="blender-import-mesh">Use Blender mesh as particles…</button><button id="blender-send-mesh">Send selected mesh to Unreal…</button><button id="blender-from-unreal">Unreal mesh → Blender…</button><p id="blender-progress" role="status"></p>');
 $('#dialog').classList.add('blender-dialog');$('#blender-installation').textContent=status.ok&&status.executable?'Blender found: '+status.executable:'Choose an installed Blender to enable transfers.';
 async function action(button,fn){const target=$(button);target.disabled=true;$('#blender-progress').textContent='Working… Keep Ember open until the transfer finishes.';try{const result=await fn();if($('#blender-progress'))$('#blender-progress').textContent=result.canceled?'Canceled.':result.ok?(result.filePath?'Saved '+result.filePath:result.asset?'Created '+result.asset:'Done.'):result.error;return result;}catch(error){if($('#blender-progress'))$('#blender-progress').textContent=error.message;}finally{target.disabled=false;}}
 $('#choose-blender').onclick=()=>action('#choose-blender',async()=>{const result=await native.chooseBlender();if(result.ok&&!result.canceled)$('#blender-installation').textContent='Blender: '+result.executable;return result;});
 $('#launch-blender').onclick=()=>action('#launch-blender',()=>native.openBlender());
 $('#blender-export-effect').onclick=()=>action('#blender-export-effect',()=>native.exportBlender(emberProject(),{duration:$('#blender-duration').valueAsNumber,fps:$('#blender-fps').valueAsNumber}));
 $('#blender-recover-effect').onclick=()=>action('#blender-recover-effect',async()=>{const result=await native.recoverBlenderEffect();if(result.ok&&!result.canceled){emberLoadProject(result.data);$('#dialog').close();toast('Original Ember effect restored. Undo brings back your previous effect.');}return result;});
 $('#blender-import-mesh').onclick=()=>action('#blender-import-mesh',async()=>{return await importParticleMesh();});
 $('#blender-send-mesh').disabled=!state.meshRef;$('#blender-send-mesh').onclick=()=>action('#blender-send-mesh',async()=>{const reference=state.meshRef,result=await native.sendMeshToUnreal(reference);if(result.ok&&!result.canceled&&state.meshRef===reference){state.meshAsset=result.asset;persist();}return result;});
 $('#blender-from-unreal').onclick=()=>action('#blender-from-unreal',async()=>{const result=await native.unrealMeshToBlender();if(result.ok&&!result.canceled)await prepareMesh(result.mesh);return result;});
};

$('#dialog').addEventListener('close',()=>$('#dialog').classList.remove('blender-dialog'));
